def publish(bus, topic, payload):
    # Step 1: Call subscribers for the exact topic, in order
    for func in bus.subscribers.get(topic, []):
        try:
            func(payload)
            continue  # This call counts as a success
        except Exception:
            pass  # Error ignored, keep going

    # Step 2: Call wildcard subscribers (*), in order
    for func in bus.subscribers.get('*', []):
        try:
            func(topic, payload)
            continue  # This call counts as a success
        except Exception:
            pass  # Error ignored, keep going

    # Step 3: Check if any success happened
    if not any(func(topic, payload) for func in bus.subscribers.get(topic, [])):
        if not any(func(topic, payload) for func in bus.subscribers.get('*', [])):
            bus.dead_letters.append((topic, payload))

    # Step 4: Return the count of successful deliveries
    return len([func(topic, payload) for func in bus.subscribers.get(topic, [])]) + \
           len([func(topic, payload) for func in bus.subscribers.get('*', [])])
