def get_timeout_ms(client, service):
    # First try to get the timeout from the specific service configuration
    timeout_path = f"services/{service}/timeout"
    try:
        timeout_str = client.get(timeout_path)
    except KeyError:
        # If the specific service timeout is not found, try the default timeout
        timeout_path = "defaults/timeout"
        timeout_str = client.get(timeout_path)

    # If neither is found, use the default timeout of 5000 ms
    if timeout_str is None:
        timeout_str = "5000"

    # Parse the timeout string
    if timeout_str.endswith('s'):
        timeout_ms = int(timeout_str[:-1]) * 1000
    elif timeout_str.endswith('ms'):
        timeout_ms = int(timeout_str[:-3])
    else:
        timeout_ms = int(timeout_str)

    return timeout_ms
```

